static int
parse_args(mrb_state *mrb, int argc, char **argv, struct _args *args)
{
char **origargv = argv;
static const struct _args args_zero = { 0 };

*args = args_zero;

for (argc--,argv++; argc > 0; argc--,argv++) {
char *item;
if (argv[0][0] != '-') break;

item = argv[0] + 1;
switch (*item++) {
case 'b':
args->mrbfile = TRUE;
break;
case 'd':
if (item[0]) {
goto append_srcpath;
}
else if (argc > 1) {
argc--; argv++;
item = argv[0];
append_srcpath:
if (!args->srcpath) {
size_t buflen;
char *buf;

buflen = strlen(item) + 1;
buf = (char *)mrb_malloc(mrb, buflen);
memcpy(buf, item, buflen);
args->srcpath = buf;
}
else {
size_t srcpathlen;
size_t itemlen;

srcpathlen = strlen(args->srcpath);
itemlen = strlen(item);
args->srcpath =
(char *)mrb_realloc(mrb, args->srcpath, srcpathlen + itemlen + 2);
args->srcpath[srcpathlen] = '\n';
memcpy(args->srcpath + srcpathlen + 1, item, itemlen + 1);
}
}
else {
printf("%s: No path specified for -d\n", *origargv);
return EXIT_SUCCESS;
}
break;
case '-':
if (strcmp((*argv) + 2, "version") == 0) {
mrb_show_version(mrb);
exit(EXIT_SUCCESS);
}
else if (strcmp((*argv) + 2, "copyright") == 0) {
mrb_show_copyright(mrb);
exit(EXIT_SUCCESS);
}
default:
return EXIT_FAILURE;
}
}

if (args->rfp == NULL) {
if (*argv == NULL) {
printf("%s: Program file not specified.\n", *origargv);
return EXIT_FAILURE;
}
else {
args->rfp = fopen(argv[0], args->mrbfile ? "rb" : "r");
if (args->rfp == NULL) {
printf("%s: Cannot open program file. (%s)\n", *origargv, *argv);
return EXIT_FAILURE;
}
args->fname = argv[0];
argc--; argv++;
}
}
args->argv = (char **)mrb_realloc(mrb, args->argv, sizeof(char*) * (argc + 1));
memcpy(args->argv, argv, (argc+1) * sizeof(char*));
args->argc = argc;

return EXIT_SUCCESS;
}

