typedef struct debug_command {
const char *cmd1;
const char *cmd2;
uint8_t len1;
uint8_t len2;
uint8_t div;
debug_command_id id;
debug_command_func func;
} debug_command;

static const debug_command debug_command_list[] = {
{"break", NULL, 1, 0, 0, DBGCMD_BREAK, dbgcmd_break},
{"continue", NULL, 1, 0, 0, DBGCMD_CONTINUE, dbgcmd_continue},
{"delete", NULL, 1, 0, 1, DBGCMD_DELETE, dbgcmd_delete},
{"disable", NULL, 3, 0, 1, DBGCMD_DISABLE, dbgcmd_disable},
{"enable", NULL, 2, 0, 1, DBGCMD_ENABLE, dbgcmd_enable},
